{"actions":[{"action":"success_contract","data":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet 127.0.0.1 6665 connects to a login prompt, and leave it running until ready.","required_artifacts":["A running QEMU process booted from /app/alpine.iso","A listening TCP service on 127.0.0.1:6665 forwarded to the guest console/serial login prompt"],"required_behaviors":["QEMU must start successfully in the background","Port 6665 on localhost must accept telnet connections","Telnet to 127.0.0.1 6665 must present a login prompt","The VM must remain running after readiness is reached"],"known_invalid_patterns":["Treating file existence or command success as sufficient without confirming the telnet-accessible login prompt","Using a different port or non-telnet access path","Stopping QEMU after boot","Reporting readiness without evidence that 127.0.0.1:6665 is listening and reaches a login prompt"],"verification_plan":["Inspect available tools and environment for qemu/telnet support and the ISO path","Launch QEMU with serial console forwarded to tcp:127.0.0.1:6665 in the background","Wait until the TCP port is listening and the guest emits a login prompt","Use receipt-backed evidence from the launch and readiness checks before finalizing"],"finalization_evidence_required":["Receipt showing QEMU launched from /app/alpine.iso in background","Receipt showing 127.0.0.1:6665 is listening","Receipt showing telnet connection reaches a login prompt"],"notes":["Prerequisites like tool availability are not success by themselves; the original task is only complete when the telnet-accessible login prompt is reachable and the VM remains running."]}}] }
{"actions":[{"action":"plan_update","data":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet 127.0.0.1 6665 connects to a login prompt, and leave it running until ready.","current_focus":"Inspect environment for qemu/telnet tooling and confirm the ISO path before launching.","implementation_approach":["Use raw_bash to locate qemu-system-* and supporting networking tools.","If available, launch QEMU with serial console redirected to tcp:127.0.0.1:6665 and run it detached/backgrounded.","Verify readiness by checking the port is listening and that a telnet connection shows the login prompt."],"validation_strategy":["Receipt-backed launch command output.","Receipt-backed port-listening evidence.","Receipt-backed telnet/login-prompt evidence."],"verification_plan":["Inspect available tools and environment for qemu/telnet support and the ISO path","Launch QEMU with serial console forwarded to tcp:127.0.0.1:6665 in the background","Wait until the TCP port is listening and the guest emits a login prompt","Use receipt-backed evidence from the launch and readiness checks before finalizing"],"known_bad_behavior":["Treating file existence or command success as sufficient without confirming the telnet-accessible login prompt","Using a different port or non-telnet access path","Stopping QEMU after boot","Reporting readiness without evidence that 127.0.0.1:6665 is listening and reaches a login prompt"],"evidence_gaps":["Need concrete evidence that qemu exists and /app/alpine.iso is accessible.","Need evidence that the guest boots to a login prompt on port 6665."],"risks":["QEMU may be absent or require a different binary name.","The ISO may need specific boot parameters or a longer wait for readiness."],"next_steps":["Probe for qemu binary and ISO presence.","Launch with appropriate serial networking if available.","Verify telnet prompt."],"finalization_evidence_required":["Receipt showing QEMU launched from /app/alpine.iso in background","Receipt showing 127.0.0.1:6665 is listening","Receipt showing telnet connection reaches a login prompt"]}}]}
{"actions":[{"action":"raw_bash","data":"set -e\ncommand -v qemu-system-x86_64 || command -v qemu-system-i386 || command -v qemu\nls -l /app/alpine.iso"},{"action":"search_files","data":{"pattern":"qemu-system-*","path":"/usr/bin"}},{"action":"search_files","data":{"pattern":"telnet","path":"/usr/bin"}}]}
